def transform(grid):
    # Replicate the horizontal three-cell motif indicated by the demo at each marker.
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 1:
                for dc, color in ((-1, 5), (0, 6), (1, 6)):
                    if 0 <= c + dc < len(row):
                        out[r][c + dc] = color
    return out
